   363→/// Verify a proof that `leaf` exists at `index` in a Merkle tree rooted at `root`.
   364→///
   365→/// The `branch` argument is the main component of the proof: it should be a list of internal
   366→/// node hashes such that the root can be reconstructed (in bottom-up order).
   367→pub fn verify_merkle_proof(
   368→    leaf: H256,
   369→    branch: &[H256],
   370→    depth: usize,
   371→    index: usize,
   372→    root: H256,
   373→) -> bool {
   374→    if branch.len() == depth {
   375→        merkle_root_from_branch(leaf, branch, depth, index) == root
   376→    } else {
   377→        false
   378→    }
   379→}
   380→
   381→/// Compute a root hash from a leaf and a Merkle proof.
   382→pub fn merkle_root_from_branch(leaf: H256, branch: &[H256], depth: usize, index: usize) -> H256 {
   383→    assert_eq!(branch.len(), depth, "proof length should equal depth");
   384→
